def validate_transaction(node, cache=None):
    # Initialize new cache for each top-level call to prevent state leakage between transactions
    if cache is None:
        cache = {}

    if node is None:
        return 0
    if node in cache:
        return cache[node]

    # Recursive step: validate children
    result = 1 + validate_transaction(node.left, cache) + validate_transaction(node.right, cache)

    cache[node] = result
    return result
